from pathlib import Path
from html import escape
p=Path(__file__).parent/'public'
base='https://tidy-csv-fmfm-stars.pages.dev'
def write(name,title,description,body,active='',script=False):
    current=lambda page: ' aria-current="page"' if page==active else ''
    path='/' if name=='index.html' else '/'+name
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | TidyCSV</title><meta name="description" content="{escape(description,quote=True)}"><meta name="google-adsense-account" content="ca-pub-8880235014376283"><link rel="canonical" href="{base}{path}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">{'<script type="module" src="/app.js"></script>' if script else ''}</head>
<body><header class="site-header"><div class="header-inner"><a class="brand" href="/" aria-label="TidyCSV home">Tidy<span>CSV</span></a><nav aria-label="Main navigation"><a href="/"{current('tool')}>Cleaner</a><a href="/guide.html"{current('guide')}>Guide</a><a href="/about.html"{current('about')}>About</a></nav></div></header>
{body}
<footer class="site-footer"><div class="footer-inner"><div><strong>TidyCSV</strong><p class="footer-note">Small, useful tools for cleaner data. Your CSV content stays in your browser.</p></div><div class="footer-links"><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a><a href="/contact.html">Contact</a></div></div></footer></body></html>'''
    (p/name).write_text(html,encoding='utf-8')

write('index.html','Clean CSV and TSV files in your browser','Trim cells, remove blank or duplicate rows, and convert delimiters with a free browser-based CSV cleaner. Files stay on your device.', '''<main>
<section class="hero"><p class="eyebrow">Less spreadsheet housekeeping</p><h1>Clean up your CSV.<br>Keep your data close.</h1><p class="lead">Trim messy cells, remove empty rows, and keep one copy of each record. Paste a table or choose a file, then download a tidy CSV or TSV.</p><div class="badges"><span class="badge">Processed in your browser</span><span class="badge">No account needed</span><span class="badge">Up to 2 MiB · UTF-8</span></div></section>
<section class="workbench" aria-label="CSV cleanup workspace"><form id="clean-form"><div class="workspace"><div><div class="section-heading"><span class="step" aria-hidden="true">1</span><h2>Your data</h2></div><label class="field-label" for="file">Choose a local CSV or TSV file</label><input id="file" type="file" accept=".csv,.tsv,.txt,text/csv,text/tab-separated-values,text/plain"><p class="hint">UTF-8 files only. The file is read on your device; it is not uploaded.</p><div class="label-line"><label class="field-label" for="source">Or paste delimited text</label><button class="text-button" id="example" type="button">Try an example</button></div><textarea id="source" spellcheck="false" placeholder="name,email&#10;Alice,alice@example.com&#10;Bob,bob@example.com" aria-describedby="input-help"></textarea><p class="hint" id="input-help">Quoted commas, escaped quotes, and multiline fields are supported. No automatic delimiter guessing.</p><div class="delimiter-row"><div><label class="field-label" for="input-delimiter">Input delimiter</label><select id="input-delimiter"><option value="comma">Comma (,)</option><option value="tab">Tab (TSV)</option><option value="semicolon">Semicolon (;)</option><option value="pipe">Pipe (|)</option></select></div><div><label class="field-label" for="output-delimiter">Output delimiter</label><select id="output-delimiter"><option value="comma">Comma (,)</option><option value="tab">Tab (TSV)</option><option value="semicolon">Semicolon (;)</option><option value="pipe">Pipe (|)</option></select></div></div><fieldset><legend>Cleanup options</legend><label class="check"><input id="trim" type="checkbox" checked><span><strong>Trim whitespace at the edges of cells</strong><span class="option-hint">Spaces inside a value remain unchanged.</span></span></label><label class="check"><input id="blank-rows" type="checkbox" checked><span><strong>Remove completely blank data rows</strong></span></label><label class="check"><input id="deduplicate" type="checkbox"><span><strong>Remove exact duplicate data rows</strong><span class="option-hint">Compared after trimming, with case preserved. The first copy wins.</span></span></label><label class="check"><input id="has-header" type="checkbox" checked><span><strong>Keep the first row as a header</strong><span class="option-hint">The first row is trimmed but never removed or compared with data rows.</span></span></label><label class="check"><input id="formula-protection" type="checkbox" checked><span><strong>Protect cells that could be spreadsheet formulas</strong><span class="option-hint">Adds an apostrophe to values beginning with =, +, -, @, tab, or carriage return. This also changes signed numbers such as -12 into text. <a href="/guide.html#formulas">Learn when to disable it.</a></span></span></label></fieldset><div class="button-row"><button type="submit">Clean data</button><button class="secondary" id="clear" type="button">Clear</button></div></div><div><div class="section-heading"><span class="step" aria-hidden="true">2</span><h2>Cleaned output</h2></div><p class="summary" id="summary">Your cleanup summary will appear here.</p><label class="field-label" for="result">Output text</label><textarea id="result" readonly spellcheck="false" placeholder="Your cleaned data will appear here."></textarea><div class="button-row output-actions"><button class="secondary" id="copy" type="button" disabled>Copy output</button><button id="download" type="button" disabled>Download file</button></div><p class="hint">Output uses CRLF between records. Downloaded values remain text; spreadsheet import settings determine how they are interpreted.</p></div></div><p class="status" id="status" role="status" aria-live="polite">Ready. Choose your options, then clean the data.</p></form><section class="preview-section" aria-label="Cleaned data preview"><h2>A quick look at the result</h2><div class="table-wrap" id="preview"><p class="hint">Clean your data to see a small table preview.</p></div></section></section>
<section class="below"><div><p class="eyebrow">A predictable cleanup</p><h2>Fix the everyday mess, then check the result.</h2><p>Exports often collect extra spaces, repeated rows, and empty lines along the way. TidyCSV handles these small repairs without asking you to build a spreadsheet formula or upload a document.</p><p>Every option has a visible effect. Duplicate removal compares the whole row, keeps the first occurrence, and respects letter case. Uneven rows stay uneven: the tool does not invent missing values, rename columns, or drop extra cells.</p><a href="/guide.html">Read the practical CSV cleanup guide →</a></div><div class="note"><h3>Keep a copy of the original.</h3><p>Trimming and duplicate removal change data. Formula protection adds a literal apostrophe to certain cells. Review the output before replacing a source file, importing contacts, or running a database job. This tool helps with formatting; it does not verify your records.</p></div></section>
<section class="faq"><p class="eyebrow">Good to know</p><h2>Questions before you clean</h2><details><summary>Does my file leave my device?</summary><p>The tool reads files and processes text in your browser. It does not send CSV contents to a server, and it does not store your input between visits. The hosting provider still handles ordinary page requests. Read the <a href="/privacy.html">privacy notice</a> for details.</p></details><details><summary>Will it remove repeated values in one column?</summary><p>No. Exact duplicate removal compares the entire row after optional trimming. Two rows with the same email but different names are both kept. Check duplicates based on a specific key in your spreadsheet or database.</p></details><details><summary>What if the file has broken quotes?</summary><p>Malformed quoting produces a readable error rather than a guessed result. Put any cell containing a delimiter, newline, or quote inside double quotes, and write an embedded quote as two quotes. The guide includes examples.</p></details><details><summary>Does it change dates, numbers, or leading zeros?</summary><p>It does not detect data types. A value such as 00123 stays 00123 in the CSV text. The default formula guard adds an apostrophe to signed values such as -12. A spreadsheet may apply its own conversions when opening the file; use its text-column import settings when exact values matter.</p></details><details><summary>Which file formats work?</summary><p>UTF-8 delimited text up to 2 MiB, using comma, tab, semicolon, or pipe separators. Excel .xlsx files, legacy text encodings, and very large datasets are outside the tool’s scope. Export those files as UTF-8 CSV or TSV first.</p></details></section></main>''','tool',True)

write('guide.html','A practical guide to cleaning CSV data','Understand CSV quoting, duplicate rows, delimiters, and spreadsheet formula protection before cleaning a file.', '''<main class="article"><p class="eyebrow">The practical guide</p><h1>A cleaner CSV, without surprises.</h1><p class="lead">CSV looks simple until a comma belongs inside a value. A few checks before cleanup can save you from shifting columns, losing records, or importing a number as text.</p><h2>1. Start with a small, reversible check</h2><p>Keep the original export and work on a copy. If you are handling an important dataset, first test a handful of representative rows: one ordinary record, one with an empty field, one with punctuation, and one with a multiline note. TidyCSV does not know what your columns mean. It can make formatting consistent, but it cannot decide whether a customer record is accurate or whether two people share an email address.</p><p>The input limit is 2 MiB, measured in UTF-8 bytes. This is suitable for small exports and pasted tables. For larger datasets, use a local data-processing tool that can stream the file rather than holding it in browser memory.</p><h2>2. Choose the actual delimiter</h2><p>A filename ending in .csv does not prove that commas separate its columns. Some exports use semicolons, especially when number formatting contains decimal commas. TSV uses tab characters. Pick comma, tab, semicolon, or pipe to match the source. TidyCSV deliberately avoids guessing: a wrong choice can produce one long column without any parsing error.</p><p>Use the preview to check that the column boundaries look right. An uneven row is preserved rather than padded or truncated. If one record has an unexpected extra cell, inspect its quoting before continuing.</p><h2>3. Know what quotes do</h2><p>A cell containing the separator must be enclosed in double quotes. The same rule applies to a newline inside a cell. To represent a literal double quote, write two consecutive double quotes within the quoted field.</p><pre><code>name,note
Alice,"Tea, coffee"
Bob,"He said ""hello"""
Cara,"First line
Second line"</code></pre><p>TidyCSV accepts LF, CRLF, or CR record endings and preserves line breaks inside quoted values. The exported file uses CRLF between records. Broken quotes, stray characters after a closing quote, and quotes inside an unquoted field produce an error. A strict error is useful: it points to data that needs attention instead of silently moving values into different columns.</p><h2>4. Trim and remove rows deliberately</h2><p>Trimming removes whitespace only at the beginning and end of each cell. It preserves spaces between words. Turn it off when leading spaces, indentation, or intentional trailing whitespace carry meaning. Blank-row removal removes data rows whose cells are all empty after trimming. A partially empty record stays in the output.</p><p>With the header option enabled, the first row is treated as a header. It is still trimmed, but it is never removed as blank or deduplicated. Header values are not added to the duplicate comparison set, so a matching data row remains. Turn this option off for files that contain records from the first line.</p><h2>5. Understand exact duplicates</h2><p>Duplicate removal compares every cell in a data row, after optional trimming. It keeps the first occurrence in its original position. Comparisons are case-sensitive: Alice and ALICE remain distinct. A row with a missing final cell differs from a row with an explicitly empty final cell. This avoids assuming that two differently structured records mean the same thing.</p><p>For deduplication by a single column, such as an order ID, use a spreadsheet or database where you can define that key and resolve conflicts. Deleting whole-row duplicates is a narrower operation.</p><h2 id="formulas">6. Review spreadsheet formula protection</h2><p>Spreadsheet programs may interpret cells beginning with =, +, -, or @ as expressions. TidyCSV’s default protection prefixes an apostrophe to these values, including values with leading whitespace, and to values beginning with a tab or carriage return. A cell such as =SUM(A1:A3) therefore becomes '=SUM(A1:A3) in the exported text.</p><p>This also affects legitimate signed numbers: -12 becomes '-12. Keep protection enabled for untrusted text you plan to view in a spreadsheet. Disable it when you require unchanged values for a trusted machine import, then use the destination’s safe text-import settings. An apostrophe is a mitigation, not a guarantee across every spreadsheet program; inspect how your chosen application imports it.</p><h2>7. Check the destination, too</h2><p>CSV carries text, not column types or formatting. TidyCSV preserves leading zeros in the output text, but your spreadsheet may convert 00123 into 123 or reinterpret a date when opening it. Choose text columns in the import dialog when exact spelling matters. Compare the row count and a few representative values after import, then keep the original until you are satisfied with the result.</p><a class="back-link" href="/">Open the CSV cleaner →</a></main>''','guide')

write('privacy.html','Privacy notice','How TidyCSV processes files locally and what happens when you visit the website.', '''<main class="article"><p class="eyebrow">Privacy</p><h1>Your data stays in your browser.</h1><p class="updated">Last updated: October 3, 2026</p><p>TidyCSV is a free browser-based utility operated by fmfm.stars. This notice describes the current service.</p><h2>CSV contents and files</h2><p>When you paste text or choose a file, JavaScript on this page reads and processes it locally in your browser. TidyCSV does not upload your CSV contents, file names, or cleaned output to our server. The tool does not save your input in cookies, local storage, or an account. Reloading or closing the page clears the tool’s working state, subject to your browser’s own form-restoration behavior.</p><p>The download button creates a file from the output already in your browser. The copy button writes the output to your clipboard only when you press it and your browser permits access. Your clipboard and downloaded files are managed by your device.</p><h2>Website delivery</h2><p>The website is hosted on Cloudflare Pages. Visiting it sends normal network-request information to the hosting provider, which can include your IP address, requested URL, browser information, and request time. Hosting infrastructure may process these details for delivery, reliability, and abuse prevention. CSV input is not included in those requests by this tool.</p><h2>Cookies, analytics, and advertising</h2><p>The current website does not set application cookies, use visitor analytics, or load advertising scripts. A publisher ownership meta tag and an ads.txt file identify the site for an advertising review; they do not display ads or send your CSV data to Google.</p><p>If advertising or analytics is added later, this notice and any required consent controls will be updated before those features run. The current local-processing behavior does not depend on an advertising account or a login.</p><h2>Contact messages</h2><p>If you email us, your email provider and ours process that message. We receive the address and content you choose to send so we can answer your request. Do not email real customer lists, payment details, credentials, or other sensitive CSV data. A small example with invented values is usually enough to explain a problem.</p><h2>Questions</h2><p>Contact <a href="mailto:fmfm.stars@gmail.com">fmfm.stars@gmail.com</a> with privacy questions. Include “TidyCSV privacy” in the subject so we can identify the service.</p><a class="back-link" href="/">Back to the cleaner →</a></main>''')

write('terms.html','Terms of use','Practical terms for using the free TidyCSV browser utility.', '''<main class="article"><p class="eyebrow">Terms</p><h1>Use the tool with a copy.</h1><p class="updated">Last updated: October 3, 2026</p><p>TidyCSV is a free browser utility operated by fmfm.stars. By using this website, you agree to these terms.</p><h2>What the service does</h2><p>The service parses and cleans UTF-8 delimited text in your browser. It supports a limited set of separators and files up to 2 MiB. It does not verify data accuracy, resolve conflicting records, provide professional advice, or guarantee compatibility with every importing application.</p><h2>Your responsibilities</h2><p>Use data that you have permission to process. Keep an original copy and review the output before relying on it. Trimming, blank-row removal, duplicate removal, and formula protection can change values or remove records. You are responsible for selecting appropriate options and checking the resulting file in its destination.</p><p>Do not use the website to interfere with the service, bypass technical limits, or perform unlawful activity. You keep your rights to the data you process; processing it with this tool does not transfer ownership to us.</p><h2>Availability and limits</h2><p>We aim to keep the utility useful, but the service is provided as available. Features and limits may change, and the website may be unavailable for maintenance or technical reasons. We make no promise that the tool will be error-free or suitable for a particular task.</p><h2>Responsibility for loss</h2><p>To the extent permitted by applicable law, we are not responsible for indirect losses or loss of data resulting from use of the tool. Nothing in these terms excludes rights or responsibilities that cannot legally be excluded.</p><h2>Updates and contact</h2><p>We may update these terms as the service changes. The date above identifies this version. For questions or bug reports, contact <a href="mailto:fmfm.stars@gmail.com">fmfm.stars@gmail.com</a>.</p><a class="back-link" href="/">Back to the cleaner →</a></main>''')

write('about.html','About TidyCSV','A focused local-processing CSV utility built for small, everyday data cleanup tasks.', '''<main class="article"><p class="eyebrow">About the tool</p><h1>A little less manual cleanup.</h1><p class="lead">TidyCSV turns a common spreadsheet chore into a short, visible workflow: choose the separator, select the repairs, and check the result.</p><h2>Why this tool exists</h2><p>Small exports tend to accumulate the same problems: a space before a name, an empty line at the end, or a repeated record from a combined list. Opening a spreadsheet to fix those issues can trigger other changes, such as date conversion or dropped leading zeros. TidyCSV keeps the process text-based and makes its options explicit.</p><h2>A focused set of choices</h2><p>The cleaner supports comma, tab, semicolon, and pipe separators, including correctly quoted multiline values. It can trim cell edges, remove blank data rows, and remove exact whole-row duplicates. It preserves row order and uneven column counts. The default formula protection adds an apostrophe to potentially active spreadsheet values; the guide explains its tradeoff for signed numbers.</p><p>The tool does not claim to clean every possible dataset. It has a 2 MiB UTF-8 input limit, does not merge records by a key, and does not infer column types. A strict parsing error is preferable to quietly guessing when quoting is broken.</p><h2>Built around local processing</h2><p>The working data stays inside the page in your browser. There is no account, backend CSV upload, or saved document history. The public website is delivered by Cloudflare Pages. You can read the <a href="/privacy.html">privacy notice</a> for the difference between ordinary website requests and file processing.</p><h2>Who operates it</h2><p>TidyCSV is operated by fmfm.stars, an independent maker of practical web tools. Suggestions and reproducible bug reports are welcome at <a href="mailto:fmfm.stars@gmail.com">fmfm.stars@gmail.com</a>. Please use invented sample data when reporting an issue.</p><a class="back-link" href="/guide.html">Learn the cleanup workflow →</a></main>''','about')

write('contact.html','Contact','Report a CSV parsing issue or ask a question about TidyCSV.', '''<main class="article"><p class="eyebrow">Contact</p><h1>Help make cleanup clearer.</h1><p class="lead">Found an unexpected result, a confusing option, or an accessibility problem? Send a concise example so we can understand it.</p><h2>Email</h2><p><a href="mailto:fmfm.stars@gmail.com?subject=TidyCSV%20feedback">fmfm.stars@gmail.com</a></p><p>Put “TidyCSV” in the subject. We cannot promise a response time, but specific reports are the most useful.</p><h2>What to include in a bug report</h2><ul><li>Your browser and device type.</li><li>The input and output delimiters you chose.</li><li>Which cleanup options were enabled.</li><li>A small input example with invented values.</li><li>The result you expected and the result you received, or the exact error message.</li></ul><div class="note"><p>Do not send real customer records, private business exports, payment information, passwords, or access tokens. Replace identifying values before sharing a sample.</p></div><h2>Before you write</h2><p>The <a href="/guide.html">cleanup guide</a> explains quoting, header preservation, exact duplicates, and formula protection. The <a href="/privacy.html">privacy notice</a> describes local processing. For a large file or a non-UTF-8 export, first reduce the example to a few representative rows.</p><a class="back-link" href="/">Back to the cleaner →</a></main>''')
